import React, { useState, useEffect } from "react";
import { Layout } from "../Component/Layout/Layout";
import { useCart } from "../context/cart";
import { useAuth } from "../context/auth";
import { NavLink, useNavigate } from "react-router-dom";
import DropIn from "braintree-web-drop-in-react";
import axios from "axios";
import toast from "react-hot-toast";
import "../style/CartStyle.css";

const CartPage = () => {
  const [auth, setAuth] = useAuth();
  const [cart, setCart] = useCart();
  const [instance, setInstance] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const [clientToken, setClientToken] = useState("");

  //total price
  const totalPrice = () => {
    try {
      let total = 0;
      cart?.map((item) => {
        total = total + item.price;
      });
      return total.toLocaleString("en-US", {
        style: "currency",
        currency: "INR",
      });
    } catch (error) {
      console.log(error);
    }
  };

  // delete item
  const removeCartItem = (pid) => {
    try {
      let myCart = [...cart];
      let index = myCart.findIndex((item) => item._id === pid);
      myCart.splice(index, 1);
      setCart(myCart);
      localStorage.setItem("cart", JSON.stringify(myCart));
    } catch (error) {
      console.log(error);
    }
  };

  //get payment gateway token
  const getToken = async () => {
    try {
      const { data } = await axios.get("/api/v1/product/braintree/token");
      setClientToken(data?.clientToken);
    } catch (error) {
      console.log(error);
    }
  };
  useEffect(() => {
    getToken();
  }, [auth?.token]);

  //handle payments
  const handlePayment = async () => {
    try {
      setLoading(true);
      const { nonce } = await instance.requestPaymentMethod();
      const { data } = await axios.post("/api/v1/product/braintree/payment", {
        nonce,
        cart,
      });
      setLoading(false);
      localStorage.removeItem("cart");
      setCart([]);
      navigate("/dashboard/user/orders");
      toast.success("Payment Completed Successfully ");
    } catch (error) {
      console.log(error);
      setLoading(false);
    }
  };
  

  return (
    <Layout>
      <div className="cart-page">
        <div className="row">
          <div className="col-md-12">
            <h1 className="text-center bg-light p-2 mb-1 heading">
              {`Hello ${auth?.token && auth?.user?.name}`}
            </h1>
            <h4 className="text-center">
              {cart && cart?.length > 0 ? (
                <>
                  {`You have ${cart.length} Items in your cart.`}
                  {!auth?.token && (
                    <span>
                      {" Please "}
                      <button className="btn btn-primary">
                        {" "}
                        <NavLink
                          to="/login" style={{ color: "white", textDecoration: "none" }} >
                          LOGIN
                        </NavLink>{" "}
                      </button>

                      {" to Checkout."}
                    </span>
                  )}
                </>
              ) : (
                "Your Cart is Empty."
              )}
            </h4>
          </div>
        </div>
        <div className="row mb-3">
          <div className="col-md-6">
            {cart?.map((p) => (
              <div className="row mb-2 flex-row mt-2 p-2" id="cart-details">
                <div className="col-md-3">
                  <img src={`/api/v1/product/product-photo/${p._id}`}
                    className="cart-img" alt={p.name} />
                </div>
                <div className="col-md-6 mt-1 detail">
                  <h6 style={{ fontFamily: "cursive" }}>{p.name}</h6>
                  <p>{p.description.substring(0, 30)}...</p>
                  <p> Selected Size:{" "}
                    {p.selectedSize ? p.selectedSize : "No size selected"}
                  </p>
                  <p style={{ color: "orangered" }}>₹{p.price}</p>
                  <button className="btn btn-danger cart-remove-btn"
                   onClick={() => removeCartItem(p._id)}> Remove </button>
                </div>
              </div>
            ))}
          </div>
          <div className="col-md-4 text-center cart-summary">
            <h2>Cart Summary</h2>
            <p>Total | Checkout | Payment</p>
            <hr />
            <h4>Total: {totalPrice()}</h4>
            {auth?.user?.address ? (
              <div className="mb-3">
                <h4>Current Address</h4>
                <h5>{auth?.user?.address}</h5>
                <button className="btn btn-outline-danger text-dark"
                  onClick={() => navigate("/dashboard/user/profile")}> Update Address </button>
              </div>
            ) : (
              <div className="mb-3">
                {auth?.token ? (
                  <button className="btn btn-outline-warning"
                    onClick={() => navigate("/dashboard/user/profile")} >
                    Update Address</button>
                ) : (
                  <button className="btn btn-outline-warning" onClick={() =>
                      navigate("/login", { state: "/cart", })}>Please Login to Checkout </button>
                )}
              </div>
            )}
            <div className="pay" >
              {!clientToken || !cart?.length ? (
                ""
              ) : (
                <>
                  <DropIn
                    options={{
                      authorization: clientToken,
                      paypal: {
                        flow: "vault",
                      },
                    }}
                    onInstance={(instance) => setInstance(instance)}
                  />
                  
                  <button className="btn btn-primary" onClick={handlePayment}
                    disabled={loading || !instance || !auth?.user?.address}>
                    {loading ? "Processing....." : "Make Payment"} </button> 
                  
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
};
export default CartPage;
