import React from 'react';
import { useState } from "react";
import { Layout } from "../../Component/Layout/Layout";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import toast,{Toaster} from 'react-hot-toast';

import "../../style/AuthStyle.css";
const Register = () => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [answer,setAnswer]=useState("");
  const navigate = useNavigate();

  // form function to not refresh page on clicking submit btn
  const handleSubmit = async(e) => {
    e.preventDefault();
    try {
      const res = await axios.post("/api/v1/auth/register", {
        name,
        email,
        password,
        phone,
        address,
        answer
      });
      if (res && res.data.success) {
        toast.success(res.data.message);
        navigate("/login");
      } else {
        toast.error(res.data.message);
      }
    } catch (error) {
      console.log(error);
      toast.error("Something went wrong");
    }
  };

  return (
    <div>
      <Layout title={"Register- TrendWave"}>
        <div className="form-container" style={{ minHeight: "120vh" }}>
          <form onSubmit={handleSubmit}>
          
          <h4 className='title'>SIGN UP FORM</h4>
          {/* <p>Fill up the <b>Required </b>Fields!!</p> */}
            <div className="mb-3">
              Name:
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="form-control"
                id="exampleInputEmail1"
                placeholder="Enter your Name"
                required
              />
            </div>
            <div className="mb-3">
              <label htmlFor="exampleInputName" className="form-label">
                Email:
              </label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="form-control"
                id="exampleInputEmail1"
                placeholder="Enter your Email"
                required
              />
            </div>
            <div className="mb-3">
              <label htmlFor="exampleInputName" className="form-label">
                Password:
              </label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="form-control"
                id="exampleInputEmail1"
                placeholder="Enter your Password"
                required
              />
            </div>
            <div className="mb-3">
              Phone:
              <input
                type="text"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                className="form-control"
                id="exampleInputEmail1"
                placeholder="Enter your Phone"
                required
              />
            </div>
            <div className="mb-3">
              <label htmlFor="exampleInputPassword1" className="form-label">
                Address:
              </label>
              <input
                type="text"
                value={address}
                onChange={(e) => setAddress(e.target.value)}
                className="form-control"
                id="exampleInputPassword1"
                placeholder="Enter your Address"
                required
              />
            </div>
            <div className="mb-3">
              <label htmlFor="exampleInputPassword1" className="form-label">
                <b>Ques.</b> Your Favourite Sports?
              </label>
              <input
                type="text"
                value={answer}
                onChange={(e) => setAnswer(e.target.value)}
                className="form-control"
                id="exampleInputPassword1"
                placeholder="Your Answer here...."
                required
              />
            </div>
           
          
            <button type="submit" className="register-btn" style={{width:"100%"}}>
              REGISTER
            </button>
            
          </form>
        </div>
      </Layout>
    </div>
  );
};

export default Register;
