import React,{useState, useEffect} from 'react';
import { Layout } from '../Component/Layout/Layout';
import useCategory from '../hooks/useCategory';
import { Link } from 'react-router-dom';

const Categories = () => {
    const categories = useCategory();
  return (
    <Layout title={"All Categories"}>
      <div className="cat">
        <div className="row container">
        <h2 className='text-center mt-4' style={{fontFamily:"serif", textTransform:"uppercase", color:"wheat "}}><b>All Categories</b></h2>
          {categories.map((c) => (
            <div className="col-md-4 mt-5 mb-3 gx-3 gy-3" key={c._id}>
              <div className="card" style={{ border: "none", backgroundColor:"transparent" }}>
                <Link to={`/category/${c.slug}`} className="btn" id='category-names'>
                  {c.name}
                </Link>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Layout>
  )
}

export default Categories