import React, { useState, useEffect } from "react";
import { Layout } from "../Component/Layout/Layout";
import axios from "axios";
import toast from "react-hot-toast";
import { useCart } from "../context/cart";
import { useParams, useNavigate } from "react-router-dom";
import "../style/ProductDetailsStyles.css";

const ProductDetails = () => {
  const params = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState({});
  const [relatedProducts, setRelatedProducts] = useState([]);
  const [cart, setCart] = useCart();
  const [selectedSize, setSelectedSize] = useState(null);

  // Handle size selection
  const handleSizeSelect = (size) => {
    setSelectedSize(size);
  };

  const handleAddToCart = () => {
    if (selectedSize || !isSizeSelectionRequired()) {
      setCart([...cart, { ...product, selectedSize }]);
      localStorage.setItem(
        "cart",
        JSON.stringify([...cart, { ...product, selectedSize }])
      );
      toast.success("Item Added to cart");
    } else {
      alert("Please select a size");
    }
  };

  // Check if size selection is required based on the category
  const isSizeSelectionRequired = () => {
    const categoryName = product?.category?.name?.toLowerCase();
    return (
      categoryName === "men" ||
      categoryName === "women" ||
      categoryName === "kids"
    );
  };

  //initalp details
  useEffect(() => {
    if (params?.slug) getProduct();
  }, [params?.slug]);

  //getProduct
  const getProduct = async () => {
    try {
      const { data } = await axios.get(
        `/api/v1/product/get-product/${params.slug}`
      );
      setProduct(data?.product);
      getSimilarProduct(data?.product._id, data?.product.category._id);
    } catch (error) {
      console.log(error);
    }
  };
  //get similar product
  const getSimilarProduct = async (pid, cid) => {
    try {
      const { data } = await axios.get(
        `/api/v1/product/related-product/${pid}/${cid}`
      );
      setRelatedProducts(data?.products);
    } catch (error) {
      console.log(error);
    }
  };
  return (
    <Layout>
      <div className="row container-fluid ms-5 product-details">
        <div className="col-md-4" id="div-product">
          <div id="img-product">
            {product._id && (
              <img src={`/api/v1/product/product-photo/${product._id}`} className="card-img-top" 
              alt={product.name} id="product-img" />
            )}
          </div>
        </div>
        <div className="col-md-5 product-details-info">
          <h1 className="text-center">Product Details</h1> <hr />
          <h6>Name : {product.name}</h6>
          <h6>Description : {product.description}</h6>
          <h6>
            Price :
            {product?.price?.toLocaleString("en-US", {
              style: "currency",
              currency: "INR",
            })}
          </h6>
          {isSizeSelectionRequired() && (
            <>
              <h6>Select Size:</h6>
              <div style={{ display: "flex" }}>
                <button className="btn ms-2 sizes" onClick={() => handleSizeSelect("S")}
                  style={{ backgroundColor: selectedSize === "S" ? "lightblue" : "white", }}> S </button>
                <button className="btn ms-2 sizes" onClick={() => handleSizeSelect("M")}
                  style={{ backgroundColor: selectedSize === "M" ? "lightblue" : "white", }}> M </button>
                <button className="btn ms-2 sizes" onClick={() => handleSizeSelect("L")}
                  style={{ backgroundColor: selectedSize === "L" ? "lightblue" : "white", }}> L </button>
                <button className="btn ms-2 sizes" onClick={() => handleSizeSelect("XL")}
                  style={{ backgroundColor: selectedSize === "XL" ? "lightblue" : "white", }}> XL </button>
              </div>
            </>
          )}
          <button className="btn btn-primary ms-1 mt-2" id="atc-btn"
            onClick={() => { handleAddToCart(); }}> ADD TO CART</button>
        </div>
      </div> <hr />
      <div className="row container similar-products">
        <h4>Similar Products ➡️</h4>
        {relatedProducts.length < 1 && (
          <p className="text-center">No Similar Products found</p>
        )}
        <div className="d-flex flex-wrap">
          {relatedProducts?.map((p) => (
            <div className="card m-2" key={p._id}>
              <img src={`/api/v1/product/product-photo/${p._id}`}
                className="card-img-top" alt={p.name} />
              <div className="card-body">
                <div className="card-name-price">
                  <h5 className="card-title">{p.name}</h5>
                  <h5 className="card-title card-price">
                    {p.price.toLocaleString("en-US", {
                      style: "currency",
                      currency: "INR",
                    })}
                  </h5>
                </div>
                <p className="card-text ">
                  {p.description.substring(0, 60)}...
                </p>
                <div className="card-name-price">
                  <button className="btn btn-info ms-1" onClick={() => navigate(`/product/${p.slug}`)}> More Details </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Layout>
  );
};

export default ProductDetails;
